	private static final class BlockingIteration implements CloseableIteration<Integer> {

		private final int blockAfterConsumed;
		private final CountDownLatch blockedHasNext = new CountDownLatch(1);
		private final CountDownLatch closed = new CountDownLatch(1);
		private final AtomicBoolean isClosed = new AtomicBoolean();
		private final AtomicBoolean availabilityBlocked = new AtomicBoolean();
		private final AtomicInteger nextCount = new AtomicInteger();
		private final AtomicInteger closeCount = new AtomicInteger();

		private BlockingIteration(int blockAfterConsumed) {
			this.blockAfterConsumed = blockAfterConsumed;
		}

		@Override
		public boolean hasNext() {
			int consumed = nextCount.get();
			boolean available = !isClosed.get() && consumed < 2;
			if (available && consumed == blockAfterConsumed && availabilityBlocked.compareAndSet(false, true)) {
				blockedHasNext.countDown();
				try {
					closed.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new IllegalStateException("Interrupted while waiting for iterator close", e);
				}
				return available;
			}
			return available;
		}

		@Override
		public Integer next() {
			if (isClosed.get()) {
				throw new NoSuchElementException("The iteration has been closed.");
			}
			int next = nextCount.getAndIncrement();
			if (next >= 2) {
				throw new NoSuchElementException("No more elements.");
			}
			return next + 1;
		}

		@Override
		public void close() {
			closeCount.incrementAndGet();
			if (isClosed.compareAndSet(false, true)) {
				closed.countDown();
			}
		}

		private boolean waitForBlockedHasNext() throws InterruptedException {
			return blockedHasNext.await(5, TimeUnit.SECONDS);
		}

		private int closeCount() {
			return closeCount.get();
		}
	}

